mapper.select:
select bm_liquid_preparation_plan_material_batch.formula_material_id, bm_liquid_preparation_plan_material_batch.material_batch_id, bm_liquid_preparation_plan_material_batch.preparation_quantity, bm_liquid_preparation_plan_material_batch.unit_id, bm_liquid_preparation_plan_material_batch.create_time, bm_liquid_preparation_plan_material_batch.material_order as `order`, bm_storage_material_batch.material_id, bm_storage_material_batch.supplier, bm_storage_material_batch.producer, bm_storage_material_batch.factory_batch_no, bm_storage_material_batch.original_batch_no, bm_storage_material_batch.report_no, bm_storage_material_batch.licence_no, bm_storage_material_batch.expired_date, bm_storage_material_batch.material_batch_no from bm_liquid_preparation_plan_material_batch left join bm_storage_material_batch on bm_liquid_preparation_plan_material_batch.material_batch_id = bm_storage_material_batch.id where bm_liquid_preparation_plan_material_batch.is_deleted = 0
and bm_liquid_preparation_plan_material_batch.liquid_preparation_plan_id = #{preparationPlanId}
and bm_liquid_preparation_plan_material_batch.formula_material_id = #{formulaMaterialId}
order by bm_storage_material_batch.material_batch_no
